def P(fonte,punto,sint,cit,aree,sub,conc,stato="annunciata",amb="nazionale",par=None,note=None,partiti=None,dest=None,cop=None):
    d={"partiti":partiti or ["fi"],"sintesi":sint,"citazione":cit,"fonte":fonte,"punto":punto,"aree":aree,"sottotema":sub,"concretezza":conc,"stato":stato,"ambito":amb}
    if par:d["parametri"]=[{"cosa":a,"valore":b} for a,b in par]
    if dest:d["destinatari"]=dest
    if cop:d["copertura"]=cop
    if note:d["note"]=note
    return d
def E(punto,sint,cit,aree,sub,conc,**k):
    k.setdefault("amb","europeo");k.setdefault("partiti",["fi","nm"])
    return P(FE,punto,sint,cit,aree,sub,conc,**k)
